import 'dart:io';
import 'package:flutter/material.dart';
import 'package:glow/glow.dart';
void main() { WidgetsFlutterBinding.ensureInitialized(); final controller = OpenGLController(); controller.initializeGL(); if (controller.openglFFI.rendererStatus()) throw StateError('renderer unexpectedly active before surface creation'); if (controller.openglFFI.addIntUniform('payload', 1) || controller.openglFFI.setIntUniform('payload', 2) || controller.openglFFI.removeUniform('payload')) throw StateError('uniform operations succeeded without renderer'); final expected = File(Platform.environment['GLOW_PAYLOAD_LIBRARY']!).resolveSymbolicLinksSync(); final mappings = File('/proc/self/maps').readAsLinesSync().where((line) => line.contains('libflutter_opengl_rust.so')).toList(); if (mappings.isEmpty || mappings.any((line) => !line.endsWith(' $expected'))) throw StateError('unexpected native library: $mappings'); final size = controller.openglFFI.getTextureSize(); if (size != const Size(-1, -1)) throw StateError('unexpected initial texture size: $size'); print('Glow native FFI loaded; inactive renderer and uninitialized texture sentinel queried'); exit(0); }
